add('water', 'move', 'Aqua Lance', 'Water gathers into a spinning orb, then a long tapering spear of water shoots out, pins the foe to the spot, and bursts into droplets.', 'new pixel spear + existing "waterwisp" sprite', {
  tick: (t, S) => { S.A.dx = t > .75 && t < 1.1 ? 4 : 0; hit(S, t, 1.05, 1.9, .9); if (t > 1.05 && t < 1.9) S.T.dx += 5; },
  f: (g, t) => {
    if (t < .8) { const k = ph(t, 0, .75); halo(g, M.x, M.y, 4 + 9 * k, '#58b8ff'); disc(g, M.x, M.y, 2 + 3 * k, '#e8f8ff'); for (let i = 0; i < 7; i++) { const a = t * 6 + i * .9, r = 24 * (1 - k) + 5; px(g, M.x + Math.cos(a) * r, M.y + Math.sin(a) * r * .7, 2, 2, i % 2 ? '#8ad8ff' : '#2a78d8'); } }
    if (t > .75 && t < 2.3) {
      const hx = lerp(M.x, TG.x + 24, ease(ph(t, .75, 1.05))), fd = 1 - ph(t, 1.9, 2.25), L = hx - M.x;
      g.save(); g.globalAlpha = fd;
      for (let x = M.x; x < hx; x++) { const u = (x - M.x) / L, hw = 1.2 + 3.6 * (1 - u * .9) * (u < .08 ? u / .08 : 1); px(g, x, M.y - hw, 1, hw * 2, '#2a78d8'); px(g, x, M.y - hw * .66, 1, hw * 1.32, '#58b8ff'); px(g, x, M.y - hw * .3, 1, hw * .6, '#e8f8ff'); if (x % 5 === 0) px(g, x, M.y + Math.sin(x * .5 - t * 30) * hw * .8, 1, 1, '#fff'); }
      spr(g, 'waterwisp', hx, M.y, 14, 0, 1); g.restore();
      if (t > 1.05 && t < 1.7) { const e = ph(t, 1.05, 1.7); star(g, TG.x - 8, TG.y, 24 * (1 - e) + 6, '#e8f8ff', 10, 0); for (let i = 0; i < 9; i++) { const a = -3 + i * .38; px(g, TG.x - 8 + Math.cos(a) * 36 * e, TG.y + Math.sin(a) * 30 * e + 26 * e * e, 2, 2, '#8ad8ff'); } }
      if (t > 1.9) { const e = ph(t, 1.9, 2.5); for (let i = 0; i < 16; i++) { const a = hash(i) * 6.28, d = 8 + 40 * e * (.4 + hash(i + 3)); px(g, TG.x + Math.cos(a) * d, TG.y + Math.sin(a) * d * .8 + 14 * e * e, 2, 2, i % 2 ? '#58b8ff' : '#e8f8ff'); } }
    }
  } });
