  tick: (t, S) => { hit(S, t, 1.0, 1.9, 1.6); if (t > 1.0 && t < 1.9) { S.T.tint = ['#fff27a', .35 * (sn(t, 20) % 2)]; S.T.dx += 6 - 5 * ph(t, 1.0, 1.9); } },
