function vineOf(g, t, i, front) {
  const N = 8, ang = i / N * 6.283 + .4, s = Math.sin(ang); if ((s > 0) !== front) return;
  const sq = 1 - .3 * ph(t, 1.45, 1.8), bx = TG.x - 6 + Math.cos(ang) * 26 * sq, by = GY - 2 + s * 6, gr = ph(t, .35 + i * .04, 1.1 + i * .04) * (1 - ph(t, 2.0, 2.5)); if (gr <= 0) return;
  let lx = bx, ly = by;
  for (let k = 0; k <= gr * 40; k++) { const u = k / 40, x = lerp(bx, TG.x - 6, u * u * .9) + Math.sin(u * 9 + i) * 2.4, y = lerp(by, GY - 74, u); line(g, lx, ly, x, y, '#1e6a2a', 3); line(g, lx, ly, x, y, '#6ad85a', 1); if (k % 5 === 3) { const d = (k % 10 === 3 ? 1 : -1); px(g, x + d * 2, y - 1, 3, 1, '#e8f0b0'); px(g, x + d * 4, y - 2, 1, 1, '#fff'); } lx = x; ly = y; }
  if (gr > .9) spr(g, i % 2 ? 'leaf1' : 'leaf2', lx, ly, 9, i * 1.2 + t * 2, 1);
  if (t > 1.5 && t < 1.95 && i % 2) px(g, lx, ly + 26, 2, 2, '#ff5a5a');
}
