const zed = (g, x, y, s, c) => { line(g, x, y, x + s, y, c, 1); line(g, x + s, y, x, y + s, c, 1); line(g, x, y + s, x + s, y + s, c, 1); };
const clampi = v => Math.max(0, Math.min(1, v));
const lunge = t => ease(ph(t, 1.3, 1.5)) * (1 - ease(ph(t, 1.5, 1.9)));
const sh = (g, t, a, b, c, al) => { if (t > a && t < b) { g.save(); g.globalAlpha = al; g.fillStyle = c; g.fillRect(0, 0, LW, LH); g.restore(); } };

