    for (let y = -ry; y <= ry; y++) { const w = Math.sqrt(Math.max(0, 1 - (y / ry) ** 2)) * rx * (.7 + .3 * gr); g.globalAlpha = k * .3; px(g, cx - w, cy + y, w * 2, 1, '#58c84a'); g.globalAlpha = k * .12; px(g, cx - w * .55, cy + y, w * 1.1, 1, '#d8ff9a'); }
    g.globalAlpha = k;
