    for (let i = 0; i < 70; i++) { const a = i / 70 * 6.283, m = wob(i), x = cx + Math.cos(a) * (rx - .8) * m, y = cy + Math.sin(a) * (ry - .8) * m; disc(g, x, y, 1.7, i % 9 === 0 ? '#d8ff9a' : '#58c84a'); }
    for (let i = 0; i < 7; i++) { const a = -2.6 + i * .24; px(g, cx + Math.cos(a) * (rx - 2), cy + Math.sin(a) * (ry - 2), 3, 1, '#e8ffc0'); px(g, cx + Math.cos(a) * (rx - 2), cy + Math.sin(a) * (ry - 2) + 1, 1, 2, '#e8ffc0'); }
    for (let i = 0; i < 5; i++) { const a = 1.0 + i * .28, x0 = cx + Math.cos(a) * rx, y0 = cy + Math.sin(a) * ry, u = (t * .55 + i * .23) % 1, len = 3 + u * (GY - 4 - y0); px(g, x0 - 1, y0, 3, len, '#58c84a'); px(g, x0, y0, 1, len, '#9aff6a'); disc(g, x0, y0 + len, 2.2, '#58c84a'); }
