    g.save(); g.globalAlpha = fd; g.translate(cx, y); g.rotate(rot); disc(g, 0, 0, 13, '#1a1a24'); disc(g, 0, -1, 11.5, '#3a3a48'); disc(g, -3, -3, 4, '#5a5a68'); px(g, -14, -10, 28, 3, '#1a1a24'); px(g, -14, -10, 28, 1, '#6a6a78'); px(g, -10, 11, 3, 5, '#1a1a24'); px(g, 7, 11, 3, 5, '#1a1a24'); if (rot > -1.2) { ell(g, 0, -9, 11, 3, '#8aff4a', 2); px(g, -8, -10, 16, 2, '#d8ff8a'); } g.restore();
