    if (t > 1.5 && t < 2.5) { const e = ph(t, 1.5, 2.4); ell(g, cx, GY - 1, 10 + 40 * e, 3 + 7 * e, '#5ac84a', 3); for (let i = 0; i < 9; i++) { const aa = -2.9 + i * .38; g.save(); g.globalAlpha = 1 - e; disc(g, cx + Math.cos(aa) * 34 * e, TG.y + Math.sin(aa) * 28 * e + 16 * e * e, 2, '#8aff4a'); g.restore(); } for (let i = 0; i < 4; i++) { const u = (t * .9 + i / 4) % 1; disc(g, cx - 14 + i * 9, TG.y + 12 - u * 40, 1.6, '#d8ff8a'); } }
