// ----- GROUND
add('ground', 'move', 'Pillar March', 'Cracks run along the ground and four jagged earth pillars of stacked rock thrust up one after another toward the foe, each taller than the last; the final one throws the foe skyward.', 'new pixel rock spires + existing "rock" sprites', {
  tick: (t, S) => { hit(S, t, 1.55, 2.1, 1.6); const u = ph(t, 1.5, 2.1); if (u > 0 && u < 1) S.T.dy = -Math.sin(u * Math.PI) * 28; },
  f: (g, t) => {
    const ax = A_X + 38; let lx = ax;
    for (let i = 0; i < 4; i++) {
      const x = lerp(104, TG.x - 6, i / 3), t0 = .5 + i * .3, hp = 28 + i * 16, w = 8 + i * 1.6, cu = ph(t, t0 - .3, t0 + .3);
      if (cu > 0) { const fd = 1 - ph(t, t0 + .75, t0 + 1.15); let px_ = lx, py = GY - 1; const n = Math.max(2, Math.floor((x - lx) / 5)); for (let s = 1; s <= n; s++) { const nx = lerp(lx, x, s / n * Math.min(1, cu * 1.4)), ny = GY - 1 + (hash(i * 9 + s) - .5) * 3; g.save(); g.globalAlpha = fd; line(g, px_, py, nx, ny, '#2a1a0a', 2); g.restore(); px_ = nx; py = ny; } }
      lx = x;
      const v = ph(t, t0, t0 + .15), fd = 1 - ph(t, t0 + .75, t0 + 1.15), h = hp * v * fd;
      if (h > 2) {
        const n = Math.max(2, Math.round(h / 13)); let y = GY - 1;
        for (let b = 0; b < n; b++) {
          const bh = h / n + 1, ww = w * (1 - b / n * .5) + (hash(i * 7 + b) - .5) * 3, ox = b ? (hash(i * 5 + b * 3) - .5) * 4 : 0, top = y - bh, lx0 = x + ox - ww;
          px(g, lx0, top, ww * 2, bh, '#4a3a24'); px(g, lx0 + 1, top + 1, ww * 2 - 2, bh - 1, '#8a6e48'); px(g, lx0 + 1, top + 1, ww * .9, bh - 1, '#b8976a'); px(g, x + ox + ww * .35, top + 1, ww * .65 - 1, bh - 1, '#64503a'); px(g, lx0 + 1, top + 1, ww * 2 - 2, 1, '#e0c890');
          px(g, lx0, top, 2, 2, '#1a1226'); px(g, x + ox + ww - 2, top, 2, 2, '#1a1226');
          for (let c = 0; c < 2; c++) line(g, x + ox - ww * .5 + c * ww * .8, top + 2, x + ox - ww * .5 + c * ww * .8 + (hash(i + b + c) - .5) * 6, top + bh - 2, '#3a2a1a', 1);
          y = top + 1;
        }
        const cw = w * .5, tip = Math.min(14, h * .45); for (let r = 0; r < tip; r++) { const hw = cw * (1 - r / tip) + .5; px(g, x - hw, y - r, hw * 2, 1, r % 4 ? '#8a6e48' : '#b8976a'); px(g, x + hw * .2, y - r, Math.max(1, hw * .8), 1, '#64503a'); }
        px(g, x - 1, y - tip, 2, 1, '#e0c890');
        if (v < 1) for (let r = 0; r < 5; r++) px(g, x - w - 3 + hash(r + i) * (w * 2 + 6), GY - 2 - hash(r + 3) * 6, 3, 2, '#6a5238');
      }
      if (v > .1 && v < 1) for (let j = 0; j < 4; j++) spr(g, 'rock' + (1 + j % 3), x + (j - 1.5) * 14 * v, GY - 8 - Math.sin(v * 3.14) * (22 + 8 * j), 8 + i, v * 6 + j, 1 - v * .3);
      if (t > t0 && t < t0 + .5) for (let j = 0; j < 3; j++) puff(g, x + (j - 1) * 12, GY - 3, 4 + 4 * ph(t, t0, t0 + .5), '#c8b078', .5 * (1 - ph(t, t0, t0 + .5)));
    }
    if (t > 1.5 && t < 1.8) star(g, TG.x - 6, TG.y, 14 * (1 - ph(t, 1.5, 1.8)) + 6, '#fff', 10, 0);
  } });

