    for (let r = 0; r < 6; r++) { const rx = (44 - r * 7) * k; for (let i = 0; i < 26; i++) { const a = i / 26 * 6.283 + t * (4 + r) * (r % 2 ? -1 : 1); px(g, cx + Math.cos(a) * rx, GY - 1 + Math.sin(a) * rx * .25, 3, 1, r % 2 ? '#a07a3a' : '#e8c878'); } }
