    for (let i = 0; i < 5; i++) { const x = TG.x - 6 + (i - 2) * 14, t0 = .6 + (2 - Math.abs(i - 2)) * -.0 + Math.abs(2 - i) * 0 + (2 - Math.abs(i - 2)) * .22, u = ph(t, t0, t0 + .16), fd = 1 - ph(t, t0 + 1.0, t0 + 1.4), h = hs[i] * u * fd; if (h < 1) continue; g.save(); g.globalAlpha = Math.min(1, fd * 1.5); spire(g, x, GY - 2, h, cols[i][0], cols[i][1], cols[i][2]); g.restore(); if (u > .9 && fd > .8 && sn(t, 4) % 2 === i % 2) star(g, x, GY - 2 - h, 3, '#fff', 4, 0); if (t > t0 && t < t0 + .4) for (let j = 0; j < 4; j++) px(g, x + (j - 1.5) * 12 * ph(t, t0, t0 + .4), GY - 6 - Math.sin(ph(t, t0, t0 + .4) * 3.1) * 20, 2, 2, cols[i][2]); }
    if (t > 1.3 && t < 1.7) star(g, TG.x - 6, TG.y, 14 * (1 - ph(t, 1.3, 1.7)) + 5, '#fff', 10, 0);
