    if (t > 1.0 && t < 1.7) { const e = ph(t, 1.0, 1.7); star(g, cx, TG.y + 6, 26 * (1 - e) + 6, '#fff', 12, 0); ell(g, cx, GY - 2, 10 + 46 * e, 3 + 9 * e, '#fff6c8', 2); for (let i = 0; i < 5; i++) puff(g, cx + (i - 2) * 10, GY - 4, 5 + 4 * e, '#c8b898', .5 * (1 - e)); }
    if (t > 1.05 && t < 2.3) for (let i = 0; i < 24; i++) { const u = (t * .8 + hash(i)) % 1; px(g, cx - 30 + hash(i + 3) * 60 + Math.sin(t * 6 + i) * 3, -4 + u * (GY + 4), 2, 3, cols[i % 5]); }
    if (t > 1.3 && t < 2.3) for (let i = 0; i < 3; i++) { const a = t * 5 + i * 2.1; plus(g, cx + Math.cos(a) * 14, TG.y - 34 + Math.sin(a) * 4, '#ffe84d'); }
