    for (let r = 0; r < 4; r++) for (let x = 40; x < 230; x += 6) { const y = GY - 6 - r * 7 + Math.sin(x * .2 + t * 8 + r) * 2; px(g, x, y, 4, 1, r % 2 ? '#ffd27a' : '#ff9a3a'); } g.restore();
