add('electric', 'move', 'Magnet Pull', 'A big horseshoe magnet swings up over the user; curved field lines sweep out and drag the foe across the floor to the user, then a zap finishes it.', 'new pixel horseshoe magnet + field lines', {
  tick: (t, S) => { hit(S, t, 1.5, 1.9, 1.6); if (t > .9 && t < 1.5) S.T.dx -= 60 * ease(ph(t, .9, 1.5)); },
  f: (g, t) => {
    const k = env(t, .15, .45, 2.0, 2.4), mx = A_X + 8, my = 38 + Math.sin(t * 3) * 2; if (k <= 0) return; g.save(); g.globalAlpha = k;
    ell(g, mx, my, 9, 9, '#d8321a', 4, Math.PI, 6.283); px(g, mx - 11, my, 5, 12, '#d8321a'); px(g, mx + 7, my, 5, 12, '#d8321a'); px(g, mx - 11, my + 12, 5, 4, '#fff'); px(g, mx + 7, my + 12, 5, 4, '#fff'); px(g, mx - 11, my + 5, 5, 3, '#2a58d8'); px(g, mx + 7, my + 5, 5, 3, '#2a58d8'); g.restore();
    if (t > .5 && t < 1.7) { const f = env(t, .5, .8, 1.5, 1.7); for (let i = 0; i < 4; i++) for (let s = 0; s < 14; s++) { const kk = ((s / 14) + t * .8) % 1, p = arcP({ x: mx, y: my + 14 }, { x: TG.x - 8, y: TG.y }, -(10 + i * 12), 1 - kk); g.save(); g.globalAlpha = f * .9; px(g, p.x, p.y, 2, 2, i % 2 ? '#fff27a' : '#ff7a7a'); g.restore(); } }
    if (t > 1.5 && t < 2.0) { const e = ph(t, 1.5, 2.0), s = sn(t, 20); bolt(g, mx, my + 14, TG.x - 8, TG.y, s, 14, '#fff27a', 2); bolt(g, mx, my + 14, TG.x - 8, TG.y, s + 4, 14, '#fff', 1); star(g, TG.x - 8, TG.y, 20 * (1 - e) + 6, '#fff27a', 10, 0); flash(g, t, 1.5, 1.6, '#fff6a8', .35); }
  } });
