    g.save(); g.globalAlpha = k; for (let i = 0; i < 9; i++) { const a = i * .7 + t * .8, r = 14 + 6 * Math.sin(i * 3 + t); disc(g, cx + Math.cos(a) * r, cy + Math.sin(a) * r * .55, 8 - (i % 3) * 1.4, i % 2 ? '#ffe84d' : '#ffd02a'); g.globalAlpha = k * .8; } g.restore();
    for (let i = 0; i < 26; i++) { const a = t * 2.5 + i * .55, r = 8 + hash(i) * 24 * (u > .99 ? 1 : .3); g.save(); g.globalAlpha = k; px(g, cx + Math.cos(a) * r, cy + Math.sin(a) * r * .6 + (t * 8 + i * 5) % 14, 1, 1, i % 3 ? '#fff6a8' : '#ffb02a'); g.restore(); }
    if (t > 1.4 && t < 1.9) { const e = ph(t, 1.4, 1.9); for (let i = 0; i < 9; i++) { const a = -.5 + i * .13; g.save(); g.globalAlpha = 1 - e; px(g, TG.x + 2 + Math.cos(a) * 34 * e, TG.y - 30 + Math.sin(a) * 20 * e + 8 * e * e, 2, 2, '#e8f8ff'); g.restore(); } star(g, TG.x - 4, TG.y - 28, 10 * (1 - e) + 4, '#fff', 8, 0); }
