add('ice', 'move', 'Black Ice', 'A sheet of glassy ice crawls out from under the foe\'s feet in cracking fractal lines; the foe loses its footing and slides.', 'new pixel ice sheet + cracks', {
  tick: (t, S) => { hit(S, t, 1.1, 1.6, 1.2); if (t > 1.1 && t < 1.8) S.T.dx += 18 * ease(ph(t, 1.1, 1.8)); },
  f: (g, t) => {
    const e = ph(t, .5, 1.2), fd = 1 - ph(t, 2.2, 2.6), cx = TG.x - 6; if (e <= 0 || fd <= 0) return; g.save(); g.globalAlpha = fd;
    ell(g, cx, GY - 2, 6 + 62 * e, 2 + 9 * e, '#c8f0ff', 2); g.globalAlpha = .45 * fd; for (let y = -8; y <= 0; y++) { const w = Math.sqrt(Math.max(0, 1 - (y / 8) ** 2)) * 66 * e; px(g, cx - w, GY - 2 + y * .6, w * 2, 1, '#98d8ff'); } g.globalAlpha = fd;
    for (let i = 0; i < 9; i++) { const a = -Math.PI * .96 + i * .4, len = 62 * e * (.5 + .5 * hash(i)); let lx = cx, ly = GY - 2; for (let s = 1; s <= 5; s++) { const k = s / 5, nx = cx + Math.cos(a) * len * k + (hash(i + s) - .5) * 4, ny = GY - 2 + Math.sin(a) * len * k * .22; line(g, lx, ly, nx, ny, '#fff', 1); lx = nx; ly = ny; } }
    for (let i = 0; i < 6; i++) if ((sn(t, 4) + i) % 3 === 0) star(g, cx - 40 + i * 16, GY - 3, 3, '#fff', 4, 0); g.restore();
    if (t > 1.1 && t < 1.6) star(g, cx, TG.y + 10, 14 * (1 - ph(t, 1.1, 1.6)) + 5, '#e8f8ff', 8, 0);
  } });
// ----- FIGHTING
add('fighting', 'move', 'Comic Combo', 'Three heavy hits land and each one pops a comic-book starburst with POW, BAM and WHAM over the foe while speed lines flash behind it.', 'new pixel comic starbursts + speed lines', {
  tick: (t, S) => { const u = ph(t, .45, .85), back = ph(t, 1.9, 2.4); S.A.dx = (TG.x - 96) * ease(u) * (1 - ease(back)); hit(S, t, 1.0, 1.9, 2); },
  b: (g, t) => { const k = env(t, .9, 1.05, 1.9, 2.2); if (k <= 0) return; g.save(); g.globalAlpha = .4 * k; for (let i = 0; i < 28; i++) { const a = i / 28 * 6.283, r0 = 22 + hash(i) * 8, r1 = 120; line(g, TG.x - 6 + Math.cos(a) * r0, TG.y + Math.sin(a) * r0, TG.x - 6 + Math.cos(a) * r1, TG.y + Math.sin(a) * r1, i % 2 ? '#fff' : '#ffe84d', 1); } g.restore(); },
  f: (g, t) => {
    const W3 = [['POW!', 1.0, -14, -26], ['BAM!', 1.3, 18, -8], ['WHAM!', 1.6, -8, 12]];
    for (const [w, t0, dx, dy] of W3) { if (t < t0 || t > t0 + .55) continue; const u = ph(t, t0, t0 + .12), fd = 1 - ph(t, t0 + .4, t0 + .55), sc = (.5 + .6 * u) * (1 + .08 * Math.sin(t * 40)), cx = TG.x - 6 + dx, cy = TG.y + dy; g.save(); g.globalAlpha = fd; g.translate(cx, cy); g.scale(sc, sc); g.beginPath(); for (let i = 0; i < 16; i++) { const a = i / 16 * 6.283, r = i % 2 ? 13 : 24; g.lineTo(Math.cos(a) * r, Math.sin(a) * r * .75); } g.closePath(); g.fillStyle = '#ffe84d'; g.fill(); g.lineWidth = 2; g.strokeStyle = '#d8321a'; g.stroke(); g.font = 'bold 10px sans-serif'; g.textAlign = 'center'; g.fillStyle = '#d8321a'; g.fillText(w, 0, 4); g.restore(); }
  } });
