add('poison', 'move', 'Acid Ceiling Drip', 'Fat green blobs of acid swell at the top of the screen, stretch and fall onto the foe one by one, leaving sizzling puddles and smoke.', 'new pixel acid drips + puddles', {
  tick: (t, S) => { hit(S, t, .95, 1.8, 1); },
  f: (g, t) => {
    for (let i = 0; i < 5; i++) {
      const t0 = .35 + i * .2, x = TG.x - 34 + i * 16 + (i % 2) * 3, sw = ph(t, t0, t0 + .35), fl = ph(t, t0 + .35, t0 + .6), by = lerp(0, GY - 8 - (i % 2) * 6, fl * fl);
      if (sw > 0 && fl < 1) { px(g, x - 1, 0, 3, 3 + 10 * sw + fl * by, '#58c84a'); disc(g, x, 4 + 10 * sw + by, 2 + 3 * sw, '#2f7a2a'); disc(g, x, 4 + 10 * sw + by, 1.6 + 2.4 * sw, '#58c84a'); px(g, x - 1, 3 + 10 * sw + by, 1, 1, '#d8ff9a'); }
      if (t > t0 + .6) { const e = ph(t, t0 + .6, t0 + 1.0), fd = 1 - ph(t, 2.0, 2.5); g.save(); g.globalAlpha = fd; ell(g, x, GY - 1, 3 + 7 * Math.min(1, e * 2), 1 + 2 * Math.min(1, e * 2), '#2f7a2a', 2); ell(g, x, GY - 1, 2 + 5 * Math.min(1, e * 2), 1 + 1 * Math.min(1, e * 2), '#9aff6a', 1); for (let j = 0; j < 3; j++) { const u = (t * .7 + j / 3 + i * .3) % 1; puff(g, x + (j - 1) * 4, GY - 4 - u * 18, 2 + u * 3, '#d8ff9a', .4 * (1 - u)); } g.restore(); }
      if (t > t0 + .6 && t < t0 + .8) { const e = ph(t, t0 + .6, t0 + .8); for (let j = 0; j < 5; j++) { const a = -3 + j * .75; px(g, x + Math.cos(a) * 12 * e, GY - 4 + Math.sin(a) * 10 * e + 6 * e * e, 2, 2, '#9aff6a'); } }
    }
  } });
// ----- GROUND
add('ground', 'move', 'Fault Line', 'A jagged crack races across the floor to the foe, the ground splits open and the foe\'s slab of earth heaves up, tilts and slams back down.', 'new pixel crack + tilting ground slab', {
  tick: (t, S) => { hit(S, t, 1.05, 1.7, 1.6); const u = ph(t, 1.0, 1.4); if (u > 0 && t < 1.55) S.T.dy = -Math.sin(u * 1.57) * 18; },
  f: (g, t) => {
    const k = ph(t, .4, 1.0), fd = 1 - ph(t, 2.2, 2.6), x1 = TG.x - 42; if (k <= 0 || fd <= 0) return; g.save(); g.globalAlpha = fd;
    let lx = A_X + 24, ly = GY - 1; const n = 22 * k; for (let s = 1; s <= n; s++) { const nx = lerp(A_X + 24, x1, s / 22), ny = GY - 1 + (hash(s * 3) - .5) * 4; line(g, lx, ly, nx, ny, '#1a0f05', 2); line(g, lx, ly, nx, ny - 1, '#ff9a3a', 1); lx = nx; ly = ny; }
    const lift = ease(ph(t, 1.0, 1.35)) * (1 - ease(ph(t, 1.5, 1.7))) * 16, tilt = lift * .5; for (let x = x1; x < TG.x + 34; x++) { const u = (x - x1) / (TG.x + 34 - x1), y = GY - 2 - lift * (.5 + .5 * (1 - u)) - tilt * (1 - u); px(g, x, y, 1, 6, '#6a4a22'); px(g, x, y, 1, 2, '#a07a3a'); px(g, x, y + 6, 1, 3, '#1a0f05'); }
    g.restore();
    if (t > 1.0 && t < 1.7) for (let i = 0; i < 6; i++) { const u = ph(t, 1.0 + i * .03, 1.6); spr(g, 'rock' + (1 + i % 3), x1 + 6 + i * 11, GY - 6 - Math.sin(u * 3.14) * (14 + i * 3), 7, u * 6 + i, 1); }
    if (t > 1.5 && t < 1.9) { const e = ph(t, 1.5, 1.9); for (let i = 0; i < 6; i++) puff(g, TG.x - 6 + (i - 3) * 9, GY - 4, 5 + 5 * e, '#c8b078', .55 * (1 - e)); star(g, TG.x - 6, GY - 12, 14 * (1 - e) + 5, '#fff', 8, 0); }
  } });
