    for (let i = 0; i < 9; i++) { const u = (t * .45 + i / 9) % 1, x = A_X + 16 + u * 140 + Math.sin(i * 2 + t * 3) * 6, y = 74 - Math.sin(u * 3.14) * 40 + Math.sin(i * 3 + t * 5) * 5, c = ['#d6f04a', '#fff', '#7ad8ff'][i % 3]; disc(g, x, y, 2, c); px(g, x + 2, y - 8, 1, 8, c); if (i % 2) px(g, x + 2, y - 8, 4, 2, c); }
