  const slug = s => s.toLowerCase().replace(/[^a-z]/g, '');
  const EFF = {}; for (const e of FX) EFF[slug(e.name)] = e;
  const state = () => ({ A: { dx: 0, dy: 0, a: 1, tint: null }, T: { dx: 0, dy: 0, a: 1, tint: null, hurt: false, rot: 0 } });
  function run(layer, e, g, mt, S) { const fn = e[layer]; if (!fn) return; try { g.save(); g.imageSmoothingEnabled = false; fn(g, mt, S); } catch (err) { if (!e.warned) { e.warned = 1; console.error('morefx', e.name, err); } } finally { g.restore(); } }
  return {
    init(imgs) { IM = imgs; },
    has: id => !!EFF[id],
    // c = { x, gy, dir, S, dx (caster travel since cast, mockup px), lift, tx (target x), ty (target centre y), img (caster sprite) }; mockup x 46 = the caster (as in the mockups)
    move(layer, id, g, mt, c) {
      const e = EFF[id]; if (!e) return; if (c.img) IM['A_' + e.type] = c.img; FX.cur = e; const S = state(); S.A.dx = c.dx || 0;
      BW = c.imgW || 50; BH = c.imgH || 56; TG.x = A_X + Math.max(60, Math.abs(c.tx - c.x) / c.S); TG.y = 108 - ((c.gy - c.lift) - c.ty) / c.S; GY = 108 + c.lift / c.S; M.x = 80; M.y = 74;
      g.save(); g.translate(c.x, c.gy - c.lift); g.scale(c.dir * c.S, c.S); g.translate(-A_X, -108); run(layer, e, g, mt, S); g.restore();
    },
  };
